package dev.theredstonee.trsclient.ornithe;
import dev.diorama.bake.*;import dev.diorama.data.ChunkSnapshot;import dev.theredstonee.trsclient.core.map.QuarterTurn;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class RotatedMapTest {
 static ChunkSnapshot fixture(){int[][] states=new int[16][];states[0]=new int[4096];byte[][] block=new byte[16][],sky=new byte[16][];block[0]=new byte[4096];sky[0]=new byte[4096];states[0][3<<8|5<<4|2]=17;block[0][3<<8|5<<4|2]=9;sky[0][3<<8|5<<4|2]=11;int[] grass=new int[256];grass[5*16+2]=0x123456;return new ChunkSnapshot(-2,1,states,block,sky,16,0,new ChunkSnapshot.Tints(grass,grass,grass,grass));}
 @Test void fourViewsRotateTerrainLightsAndTintsWithoutMutatingTheSource(){ChunkSnapshot source=fixture();int wx=-30,wz=21;for(int q=0;q<4;q++){ChunkSnapshot rotated=source.rotated(q);int u=QuarterTurn.blockU(wx,wz,q),d=QuarterTurn.blockDepth(wx,wz,q);assertEquals(u>>4,rotated.chunkX);assertEquals(d>>4,rotated.chunkZ);assertEquals(17,rotated.section(0)[3<<8|(d&15)<<4|(u&15)]);assertEquals(9,rotated.blockLight(0,u&15,3,d&15));assertEquals(11,rotated.skyLight(0,u&15,3,d&15));assertEquals(0x123456,rotated.tints.grass()[(d&15)*16+(u&15)]);}assertEquals(17,source.section(0)[3<<8|5<<4|2]);}
 @Test void structuresChangeWhichFacesAreVisibleAtEachCardinalAngle(){BlockLooks looks=new BlockLooks();looks.shapes=new float[][]{new float[]{0,0,0,1,1,1},new float[]{0,0,0,1,1,.25f}};looks.shape[17]=1;float[] east=looks.rotated(1).shapes[1];assertArrayEquals(new float[]{.75f,0,0,1,1,1},east,.00001f);assertArrayEquals(new float[]{0,0,0,1,1,.25f},looks.shapes[1]);}
 @Test void identicalChunksAndLightOnlyChangesHaveDifferentCacheSemantics(){ChunkSnapshot a=fixture(),b=fixture();assertTrue(a.sameContent(b));assertEquals(a.fingerprint(),b.fingerprint());ChunkSnapshot changed=fixture();changed.section(0)[0]=3;assertFalse(a.sameContent(changed));assertNotEquals(a.fingerprint(),changed.fingerprint());}
}
